func ptrTransferChange(p unsafe.Pointer, c int32) any {
	r := (*edisync.TransferChange)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.ShipmentLinkID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Direction))
	case 4:
		return &r.ChangeType
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return (*string)(unsafe.Pointer(&r.ConflictStatus))
	case 7:
		return &r.ConflictReason
	case 8:
		return &r.IdempotencyKey
	case 9:
		return &r.SourceShipmentVersion
	case 10:
		return &r.TargetShipmentVersion
	case 11:
		return &r.Payload
	case 12:
		return &r.Diff
	case 13:
		return (*string)(unsafe.Pointer(&r.ReviewedByID))
	case 14:
		return &r.ReviewedAt
	case 15:
		return (*string)(unsafe.Pointer(&r.AppliedByID))
	case 16:
		return &r.AppliedAt
	case 17:
		return &r.FailureReason
	case 18:
		return &r.SearchVector
	case 19:
		return &r.Rank
	case 20:
		return &r.Version
	case 21:
		return &r.CreatedAt
	case 22:
		return &r.UpdatedAt
	}
	return nil
}

func valueTransferChange(p unsafe.Pointer, c int32) any {
	r := (*edisync.TransferChange)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.ShipmentLinkID)
	case 3:
		return string(r.Direction)
	case 4:
		return r.ChangeType
	case 5:
		return string(r.Status)
	case 6:
		return string(r.ConflictStatus)
	case 7:
		if r.ConflictReason == "" {
			return nil
		}
		return r.ConflictReason
	case 8:
		return r.IdempotencyKey
	case 9:
		return r.SourceShipmentVersion
	case 10:
		return r.TargetShipmentVersion
	case 11:
		if r.Payload == nil {
			return keel.EmptyJSONObject
		}
		return r.Payload
	case 12:
		if r.Diff == nil {
			return keel.EmptyJSONObject
		}
		return r.Diff
	case 13:
		if r.ReviewedByID == "" {
			return nil
		}
		return string(r.ReviewedByID)
	case 14:
		if r.ReviewedAt == nil {
			return nil
		}
		return *r.ReviewedAt
	case 15:
		if r.AppliedByID == "" {
			return nil
		}
		return string(r.AppliedByID)
	case 16:
		if r.AppliedAt == nil {
			return nil
		}
		return *r.AppliedAt
	case 17:
		if r.FailureReason == "" {
			return nil
		}
		return r.FailureReason
	case 18:
		return r.SearchVector
	case 19:
		return r.Rank
	case 20:
		return r.Version
	case 21:
		return r.CreatedAt
	case 22:
		return r.UpdatedAt
	}
	return nil
}

